import {initializeApp} from "firebase/app";
import {getFirestore,connectFirestoreEmulator,addDoc,collection} from "firebase/firestore";
const app=initializeApp({projectId:"demo-reading-club"});
const db=getFirestore(app);connectFirestoreEmulator(db,"127.0.0.1",8080);
const reference=await addDoc(collection(db,"books"),{title:"Garden Days",pages:40});
console.log(reference.id);
